参考实现（JavaScript，闭区间写法）：
function binarySearch(a, target) {
  let lo = 0, hi = a.length - 1;
  while (lo <= hi) {
    const mid = lo + ((hi - lo) >> 1);
    if (a[mid] === target) return mid;
    if (a[mid] < target) lo = mid + 1;
    else hi = mid - 1;
  }
  return -1;
}
时间复杂度 O(log n)，空间 O(1)。

参考实现（JavaScript）：
function reverseList(head) {
  let prev = null, cur = head;
  while (cur) {
    const next = cur.next;
    cur.next = prev;
    prev = cur;
    cur = next;
  }
  return prev;
}
时间复杂度 O(n)：每个结点访问一次；额外空间 O(1)：只用了三个指针。

参考实现（JavaScript，Kadane 算法）：
function maxSubArray(nums) {
  let best = -Infinity, cur = 0;
  for (const x of nums) {
    cur = Math.max(x, cur + x);
    best = Math.max(best, cur);
  }
  return best;
}
时间复杂度 O(n)，额外空间 O(1)。

参考实现（JavaScript，O(n²) 动态规划）：
function lisLen(a) {
  const n = a.length;
  if (!n) return 0;
  const dp = new Array(n).fill(1);
  for (let i = 1; i < n; i++)
    for (let j = 0; j < i; j++)
      if (a[j] < a[i]) dp[i] = Math.max(dp[i], dp[j] + 1);
  return Math.max(...dp);
}
优化思路：可优化到 O(n log n)——维护数组 tails，其中 tails[k] 表示「长度为 k+1 的递增子序列的最小结尾值」；遍历每个元素用二分查找定位并更新 tails（贪心 + 二分，原理是结尾越小越有潜力延长）。

参考实现（JavaScript，哈希表一次遍历）：
function twoSum(nums, target) {
  const seen = new Map();
  for (let i = 0; i < nums.length; i++) {
    const need = target - nums[i];
    if (seen.has(need)) return [seen.get(need), i];
    seen.set(nums[i], i);
  }
  return [];
}
时间复杂度 O(n)，额外空间 O(n)。

参考实现（JavaScript，Lomuto 分区）：
function quickSort(a, lo = 0, hi = a.length - 1) {
  if (lo >= hi) return a;
  const p = partition(a, lo, hi);
  quickSort(a, lo, p - 1);
  quickSort(a, p + 1, hi);
  return a;
}
function partition(a, lo, hi) {
  const pivot = a[hi];
  let i = lo;
  for (let j = lo; j < hi; j++)
    if (a[j] < pivot) { [a[i], a[j]] = [a[j], a[i]]; i++; }
  [a[i], a[hi]] = [a[hi], a[i]];
  return i;
}
性能：平均 O(n log n)、最坏 O(n²)（已排序/逆序且固定取端点为枢轴时退化）；原地分区、平均空间 O(log n) 递归栈。实践中用随机枢轴或三数取中规避最坏。

参考实现（JavaScript，迭代 + 哑结点）：
function mergeTwoLists(l1, l2) {
  const dummy = { val: 0, next: null };
  let tail = dummy;
  while (l1 && l2) {
    if (l1.val <= l2.val) { tail.next = l1; l1 = l1.next; }
    else { tail.next = l2; l2 = l2.next; }
    tail = tail.next;
  }
  tail.next = l1 || l2;
  return dummy.next;
}
时间复杂度 O(m + n)，额外空间 O(1)（复用原结点）。

questions.stem:
分析下面这段朴素递归求斐波那契数的代码的时间复杂度，并说明原因与改进方向：
function fib(n) {
  return n <= 1 ? n : fib(n - 1) + fib(n - 2);
}
